def predict(probe):
    frame = probe["frame"]
    level = probe.get("level", 0)
    actions = probe.get("actions", [])

    grid = [list(row) for row in frame]
    slots = [(15,19),(22,26),(29,33),(36,40),(43,47)]

    def find_p():
        for i,(a,b) in enumerate(slots):
            if grid[48][a] == '0':
                return i
        return 0

    def get_pattern(i):
        a,b = slots[i]
        return tuple(grid[r][c] for r in range(52,57) for c in range(a,b+1))

    def set_pattern(i, pat):
        a,b = slots[i]
        k=0
        for r in range(52,57):
            for c in range(a,b+1):
                grid[r][c]=pat[k]; k+=1

    def rot_cw(pat):
        # pat is 25 chars row-major 5x5
        g=[[pat[r*5+c] for c in range(5)] for r in range(5)]
        ng=[[g[4-c][r] for c in range(5)] for r in range(5)]
        return tuple(ng[r][c] for r in range(5) for c in range(5))

    def invert(pat):
        return tuple('5' if ch=='7' else ('7' if ch=='5' else ch) for ch in pat)

    # counter
    def get_counter():
        cnt = sum(1 for c in range(64) if grid[63][c]=='4')
        return 64 - cnt  # remaining

    p = find_p()
    counter = get_counter()
    patterns = [get_pattern(i) for i in range(5)]

    steps=[]
    state="NOT_FINISHED"
    levels_done=0

    for act in actions:
        if state=="GAME_OVER":
            if act=="RESET":
                # reset: restore initial-ish; we can't fully, but reset counter/strip
                counter=64
                p=0
                state="NOT_FINISHED"
                # patterns reset unknown; leave
            steps.append({"changes":{},"levels":0,"state":state})
            continue
        if act=="RESET":
            counter=64; p=0
            steps.append({"changes":{},"levels":0,"state":"NOT_FINISHED"})
            continue
        changes={}
        if act=="ACTION4":
            p=(p+1)%5
            # update strip
            for i,(a,b) in enumerate(slots):
                col='0' if i==p else '3'
                for r in (48,49,59,60):
                    for c in range(a,b+1):
                        if grid[r][c]!=col:
                            grid[r][c]=col
                            changes[f"{r},{c}"]=col
        elif act=="ACTION3":
            p=(p-1)%5
            for i,(a,b) in enumerate(slots):
                col='0' if i==p else '3'
                for r in (48,49,59,60):
                    for c in range(a,b+1):
                        if grid[r][c]!=col:
                            grid[r][c]=col
                            changes[f"{r},{c}"]=col
        elif act=="ACTION1":
            patterns[p]=rot_cw(patterns[p])
            a,b=slots[p]
            k=0
            for r in range(52,57):
                for c in range(a,b+1):
                    if grid[r][c]!=patterns[p][k]:
                        grid[r][c]=patterns[p][k]; changes[f"{r},{c}"]=patterns[p][k]
                    k+=1
        elif act=="ACTION2":
            patterns[p]=invert(patterns[p])
            a,b=slots[p]
            k=0
            for r in range(52,57):
                for c in range(a,b+1):
                    if grid[r][c]!=patterns[p][k]:
                        grid[r][c]=patterns[p][k]; changes[f"{r},{c}"]=patterns[p][k]
                    k+=1
        # counter decrement
        counter-=1
        if counter<=0:
            state="GAME_OVER"
        # goal guess: all patterns identical
        if len(set(patterns))==1 and state=="NOT_FINISHED":
            state="WIN"; levels_done=1
        steps.append({"changes":changes,"levels":levels_done,"state":state})
    return {"steps":steps}
